mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xy = rot(time * 0.4) * p.xy;
  float r = length(p.xy);
  float a = atan(p.y, p.x);
  float spiralR = 0.26 * exp(0.19 * a);
  return length(vec3(r - spiralR, p.z, 0.0)) - 0.13 * spiralR;
}
shader_body {
